import{_ as t,o as i,c as a,a2 as s}from"./chunks/framework.ChIlRNAd.js";const p=JSON.parse('{"title":"Administration","description":"","frontmatter":{},"headers":[],"relativePath":"fr/guide/admin.md","filePath":"fr/guide/admin.md"}'),r={name:"fr/guide/admin.md"};function l(o,e,n,u,d,c){return i(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="administration" tabindex="-1">Administration <a class="header-anchor" href="#administration" aria-label="Permalink to &quot;Administration&quot;">​</a></h1><p>La page <strong>Administration</strong> est réservée aux utilisateurs ayant le rôle <strong>admin</strong>. Elle permet de gérer les utilisateurs, de surveiller les jobs et de consulter les statistiques système.</p><hr><h2 id="gestion-des-utilisateurs" tabindex="-1">Gestion des utilisateurs <a class="header-anchor" href="#gestion-des-utilisateurs" aria-label="Permalink to &quot;Gestion des utilisateurs&quot;">​</a></h2><h3 id="liste-des-utilisateurs" tabindex="-1">Liste des utilisateurs <a class="header-anchor" href="#liste-des-utilisateurs" aria-label="Permalink to &quot;Liste des utilisateurs&quot;">​</a></h3><p>Le tableau affiche tous les utilisateurs de l&#39;instance avec :</p><ul><li>Email, nom d&#39;affichage, avatar</li><li>Rôle (user / admin)</li><li>Nombre de comptes Gmail connectés</li><li>Espace de stockage utilisé</li><li>Date de dernière connexion</li><li>Statut (actif / inactif)</li></ul><p>La liste est paginée et permet la recherche par email ou nom.</p><blockquote><p>📸 <em>Capture d&#39;écran suggérée : tableau des utilisateurs avec les colonnes mentionnées</em></p></blockquote><h3 id="modifier-un-utilisateur" tabindex="-1">Modifier un utilisateur <a class="header-anchor" href="#modifier-un-utilisateur" aria-label="Permalink to &quot;Modifier un utilisateur&quot;">​</a></h3><p>Cliquez sur un utilisateur pour modifier :</p><ul><li><strong>Rôle</strong> : promouvoir en admin ou rétrograder en user</li><li><strong>Quotas</strong> : <ul><li>Nombre maximal de comptes Gmail (défaut : 5)</li><li>Quota de stockage des archives (défaut : 1 Go)</li></ul></li><li><strong>Statut</strong> : activer ou désactiver le compte</li></ul><blockquote><p>📸 <em>Capture d&#39;écran suggérée : formulaire de modification d&#39;un utilisateur avec les champs rôle, quotas et statut</em></p></blockquote><hr><h2 id="jobs-globaux" tabindex="-1">Jobs globaux <a class="header-anchor" href="#jobs-globaux" aria-label="Permalink to &quot;Jobs globaux&quot;">​</a></h2><p>L&#39;onglet <strong>Jobs</strong> affiche les jobs de <strong>tous les utilisateurs</strong> avec :</p><ul><li>L&#39;utilisateur qui a lancé le job</li><li>Le type et le statut</li><li>La progression</li><li>La date de création</li></ul><p>Les administrateurs peuvent annuler n&#39;importe quel job en cours.</p><hr><h2 id="statistiques-systeme" tabindex="-1">Statistiques système <a class="header-anchor" href="#statistiques-systeme" aria-label="Permalink to &quot;Statistiques système&quot;">​</a></h2><p>L&#39;onglet <strong>Statistiques</strong> affiche :</p><ul><li>Nombre total d&#39;utilisateurs</li><li>Nombre de comptes Gmail connectés</li><li>Espace de stockage total utilisé</li><li>Nombre de jobs en cours</li></ul><blockquote><p>📸 <em>Capture d&#39;écran suggérée : tableau de bord admin avec les statistiques système</em></p></blockquote><hr><h2 id="verification-d-integrite" tabindex="-1">Vérification d&#39;intégrité <a class="header-anchor" href="#verification-d-integrite" aria-label="Permalink to &quot;Vérification d&#39;intégrité&quot;">​</a></h2><p>Les administrateurs peuvent vérifier la cohérence entre les fichiers EML sur le NAS et l&#39;index PostgreSQL :</p><ul><li><strong>Fichiers manquants</strong> : référencés en base mais absents du disque</li><li><strong>Fichiers orphelins</strong> : présents sur le disque sans enregistrement en base</li><li><strong>Fichiers corrompus</strong> : fichiers vides (0 octets)</li></ul><p>La vérification peut être lancée manuellement ou s&#39;exécute automatiquement <strong>chaque nuit à 3h</strong>. En cas de problème, un événement webhook <code>integrity.failed</code> est déclenché.</p><blockquote><p>📸 <em>Capture d&#39;écran suggérée : résultat d&#39;une vérification d&#39;intégrité (statut sain / problèmes détectés)</em></p></blockquote>',29)])])}const g=t(r,[["render",l]]);export{p as __pageData,g as default};
